INSERT INTO `config` (`name`, `value`, `title`, `description`, `field_id`, `type_id`, `editable`) VALUES ('saml_logout_url', '', 'Single Sign-On Logout URL', 'The logout URL for the SAML identity provider to redirect users to upon logout. You can use {SCHOOLBOX_ADDRESS} in the URL which will be automatically replaced with the correct address, e.g. schoolbox.school.edu', '1', (SELECT `id` FROM lu_config_type WHERE `type` like 'Security'), 'true');
